-- =============================================================================
-- Nationwide 50-state US Senate primaries (2026 cycle)
-- =============================================================================
-- Human-readable race id lives in general_slug (e.g. tx-senate-2026) and slug
-- (e.g. tx-senate-2026-dem). primaries.id stays UUID. state is the two-letter
-- code required by primaries_state_code_check; office / office_name = US Senate.
-- Three mock candidates per primary carry distinct ideological_vector jsonb
-- coordinates for the matching engine, plus a short primary_questions queue.
-- Applied after ./seed.sql via supabase/config.toml [db.seed] sql_paths.
-- =============================================================================

